PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE users (id TEXT PRIMARY KEY, phone TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, data TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE admins (id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, data TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE sessions (id_hash TEXT PRIMARY KEY, actor_type TEXT NOT NULL, actor_id TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE deposits (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, data TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE withdraws (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, data TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE trades (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, data TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE funds (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, data TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE chats (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, data TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE kycs (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, data TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE transaction_ledger (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, type TEXT NOT NULL, amount REAL NOT NULL, balance_before REAL NOT NULL, balance_after REAL NOT NULL, reference_id TEXT, detail TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE notifications (id TEXT PRIMARY KEY, type TEXT NOT NULL, target TEXT, title TEXT NOT NULL, message TEXT NOT NULL, read_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE audit_log (id INTEGER PRIMARY KEY AUTOINCREMENT, actor TEXT, action TEXT, target TEXT, detail TEXT, ip TEXT, created_at TEXT NOT NULL);
CREATE TABLE idempotency_keys (key TEXT PRIMARY KEY, operation TEXT NOT NULL, response TEXT NOT NULL, created_at TEXT NOT NULL);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_deposits_user ON deposits(user_id, created_at);
CREATE INDEX idx_withdraws_user ON withdraws(user_id, created_at);
CREATE INDEX idx_trades_user ON trades(user_id, created_at);
CREATE INDEX idx_funds_user ON funds(user_id, created_at);
CREATE INDEX idx_chats_user ON chats(user_id, created_at);
CREATE INDEX idx_kycs_user ON kycs(user_id, created_at);
CREATE INDEX idx_ledger_user ON transaction_ledger(user_id, created_at);
CREATE INDEX idx_notifications_created ON notifications(created_at);
CREATE INDEX idx_users_created ON users(created_at);
CREATE INDEX idx_users_name ON users(json_extract(data,'$.name'));
CREATE INDEX idx_sessions_actor ON sessions(actor_type, actor_id);
CREATE INDEX idx_sessions_expires ON sessions(expires_at);
CREATE INDEX idx_admins_created ON admins(created_at);
CREATE INDEX idx_notifications_target ON notifications(target, created_at);
